// 1️⃣ Extraer los datos del resultado de ElevenLabs
const audioBase64 = $input.first().json.audio_base64;
const alignment = $input.first().json.alignment || $input.first().json.normalized_alignment;

// 2️⃣ Combinar los arrays de caracteres con sus tiempos
const chars = alignment.characters;
const starts = alignment.character_start_times_seconds;
const ends = alignment.character_end_times_seconds;

const combined = chars.map((c, i) => ({
  char: c,
  start: starts[i],
  end: ends[i],
}));

// 3️⃣ Agrupar caracteres en palabras con tiempos promedio
const words = [];
let currentWord = '';
let startTime = null;
let endTime = null;

for (let i = 0; i < combined.length; i++) {
  const { char, start, end } = combined[i];

  // Detectar si es parte de una palabra (letras o números)
  if (char.match(/[^\s.,!?;:]/)) {
    if (currentWord === '') startTime = start;
    currentWord += char;
    endTime = end;
  }

  // Si es un separador o fin del texto, guardar palabra
  const nextChar = combined[i + 1]?.char ?? ' ';
  if (char.match(/\s/) || nextChar.match(/\s/) || i === combined.length - 1) {
    if (currentWord.trim().length > 0) {
      words.push({
        word: currentWord.trim(),
        start: startTime,
        end: endTime
      });
      currentWord = '';
      startTime = null;
      endTime = null;
    }
  }
}

// 4️⃣ Convertir el array de palabras a texto JSON
const wordsJson = JSON.stringify(words, null, 2);

// 5️⃣ Devolver ambos archivos: audio (.mp3) y timestamps (.json)
return [
  {
    json: {
      message: "Archivos generados correctamente",
      wordCount: words.length
    },
    binary: {
      audio: {
        data: audioBase64,
        mimeType: 'audio/mpeg',
        fileName: `voz_${Date.now()}.mp3`
      },
      timestamps: {
        data: btoa(unescape(encodeURIComponent(wordsJson))), // asegura compatibilidad total
        mimeType: 'application/json',
        fileName: `timestamps_${Date.now()}.json`
      }
    }
  }
];

const inputBinary = $input.first().binary || {};

return [
  {
    json: { fileType: 'audio' },
    binary: { data: inputBinary.audio }
  },
  {
    json: { fileType: 'timestamps' },
    binary: { data: inputBinary.timestamps }
  }
];
